// all-exceptions.filter.ts
import { ArgumentsHost, Catch, ExceptionFilter, HttpException, HttpStatus } from '@nestjs/common';
import { Request, Response } from 'express';

@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    const statusCode =
      exception instanceof HttpException ? exception.getStatus() : HttpStatus.INTERNAL_SERVER_ERROR;
    const message =
      exception instanceof HttpException ? exception.getResponse() : 'Internal server error';

    // The ONE envelope shape every caller of the API can rely on.
    response.status(statusCode).json({
      statusCode,
      message,
      error: exception instanceof Error ? exception.name : 'Error',
      timestamp: new Date().toISOString(),
      path: request.url,
    });
  }
}

// main.ts
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { AllExceptionsFilter } from './all-exceptions.filter';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);
  app.useGlobalFilters(new AllExceptionsFilter());
  await app.listen(3000);
}
bootstrap();

// users.service.ts
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { Order } from './order.entity';

@Injectable()
export class UsersService {
  constructor(
    @InjectRepository(User) private readonly userRepository: Repository<User>,
    @InjectRepository(Order) private readonly orderRepository: Repository<Order>,
  ) {}

  async findById(id: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id } });
    if (!user) {
      // Expected domain case, but reported as a plain Error — not a typed
      // NotFoundException — so its "not found" nature disappears the moment
      // a catch block intercepts it.
      throw new Error('User not found');
    }
    return user;
  }

  async findOrdersByUserId(id: string): Promise<Order[]> {
    const user = await this.findById(id);
    // repository.find can also surface a raw driver/ORM error (bad connection,
    // malformed query) whose .message may carry table/column/query details.
    return this.orderRepository.find({ where: { userId: user.id } });
  }
}

// users.controller.ts
import { Controller, Get, Param } from '@nestjs/common';
import { UsersService } from './users.service';

@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Get(':id')
  async getUser(@Param('id') id: string) {
    try {
      const user = await this.usersService.findById(id);
      return user;
    } catch (err) {
      // Local try/catch: bypasses AllExceptionsFilter entirely.
      // Raw err.message goes straight to the client (hide-by-default violation).
      // No logger.error(...) call — an unexpected failure here leaves no trace.
      return { error: err.message };
    }
  }

  @Get(':id/orders')
  async getUserOrders(@Param('id') id: string) {
    try {
      const orders = await this.usersService.findOrdersByUserId(id);
      return orders;
    } catch (err) {
      // Same pattern repeated: every handler now decides its own error shape
      // instead of the one centralized envelope AllExceptionsFilter defines.
      return { error: err.message };
    }
  }
}
